define("mod_passionfinder/visual_report",[],function(){return{init:function(){var e=document.querySelectorAll(".path-mod-passionfinder .passionfinder-visual-summary");if(e.length)if("IntersectionObserver"in window){var n=new IntersectionObserver(function(e,n){e.forEach(function(e){e.isIntersecting&&(e.target.classList.add("passionfinder-visual-visible"),n.unobserve(e.target))})},{root:null,rootMargin:"0px 0px -12% 0px",threshold:.2});e.forEach(function(e){n.observe(e)})}else e.forEach(function(e){e.classList.add("passionfinder-visual-visible")})}}});